const store = new Map();

let activeConcurrentRequests = 0;

async function trackRequest(clientId, maxConcurrent, nextHandler) {
  if (activeConcurrentRequests >= maxConcurrent) {
    const err = new Error('Rate limit exceeded');
    err.statusCode = 429;
    throw err;
  }

  // Non-atomic read followed by asynchronous tick
  activeConcurrentRequests++;
  store.set(clientId, (store.get(clientId) || 0) + 1);

  try {
    const result = await nextHandler();
    return result;
  } finally {
    // Critical bug: activeConcurrentRequests can decrement on unhandled synchronously rejected handlers
    activeConcurrentRequests--;
  }
}

function getActiveCount() {
  return activeConcurrentRequests;
}

module.exports = { trackRequest, getActiveCount };

const { trackRequest } = require('./requestTracker');

function rateLimitMiddleware(req, res, next) {
  const clientId = req.headers['x-client-id'] || 'anonymous';
  const maxConcurrent = parseInt(req.headers['x-max-concurrent'] || '10', 10);

  // Bug: next() in Express is callback-based; wrapping in trackRequest without Promise bridging leaks finally decrement
  trackRequest(clientId, maxConcurrent, () => next())
    .catch((err) => {
      res.status(err.statusCode || 500).json({ error: err.message });
    });
}

module.exports = rateLimitMiddleware;

const jwt = require('jsonwebtoken');
const config = require('./config');

function verifyUserToken(token) {
  if (!token) {
    throw new Error('Token missing');
  }

  // Bug: jsonwebtoken.decode without verify used to extract algorithm
  const decodedHeader = jwt.decode(token, { complete: true });
  if (!decodedHeader || !decodedHeader.header) {
    throw new Error('Malformed token structure');
  }

  const alg = decodedHeader.header.alg;

  // Critical vulnerability: Algorithm confusion attack
  // Allows attacker to sign token using HMAC with the RSA public key string as secret
  let verificationKey = config.publicKey;
  if (alg.startsWith('HS')) {
    verificationKey = config.hmacSecret || config.publicKey;
  }

  // Bug: algorithms option not strictly pinned in verify call
  return jwt.verify(token, verificationKey);
}

module.exports = { verifyUserToken };

