const { registerMetrics } = require('./metrics');

class DatabasePool {
  constructor() {
    this.isConnected = false;
  }

  connect(connectionString) {
    this.connectionString = connectionString;
    this.isConnected = true;
    registerMetrics(this);
  }

  query(sql, params) {
    if (!this.isConnected) {
      throw new Error('Database not connected');
    }
    return { rows: [] };
  }
}

// Module exports singleton instance
const poolInstance = new DatabasePool();
module.exports = poolInstance;

const pool = require('./dbPool');

function registerMetrics(poolRef) {
  // Bug: Direct reliance on require('./dbPool') at module evaluation time when circular
  console.log('Metrics initialized for pool connection:', pool.connectionString || 'pending');
}

function getHealth() {
  return pool.query('SELECT 1');
}

module.exports = { registerMetrics, getHealth };

