from typing import Callable, Dict, List, Any

class EventBus:
    def __init__(self):
        self._subscribers: Dict[str, List[Callable[[Dict[str, Any]], None]]] = {}

    def subscribe(self, event_name: str, handler: Callable[[Dict[str, Any]], None]):
        self._subscribers.setdefault(event_name, []).append(handler)

    def publish(self, event_name: str, payload: Dict[str, Any]):
        for handler in self._subscribers.get(event_name, []):
            # Bug: Raw dictionary reference passed to all listeners sequentially
            handler(payload)

def apply_tax_and_discounts(event_payload: dict):
    items = event_payload.get('items', [])
    for item in items:
        # Critical bug: In-place mutation of price and addition of tax modifies original payload for subsequent subscribers
        item['price'] = item['price'] * 0.90
    event_payload['discount_applied'] = True

def audit_order_total(event_payload: dict):
    # Runs after discount_service in subscriber list
    original_total = sum(item['price'] for item in event_payload.get('items', []))
    if original_total > 1000:
        print("Flagging high value transaction for review:", original_total)
